import { expect } from 'chai'
import { readFileSync } from 'node:fs'
import { parseLibreViewTime, readPatientData } from '../../src/common/DeviceExports.js'

const at = (h: number, m = 0) => new Date(2026, 9, 5, h, m)

/** a LibreView export as downloaded in the UK (shortened) */
const libreView = [
    "Glucose Data,Generated on,05-10-2026 20:00 UTC,Generated by,A Person",
    "Device,Serial Number,Device Timestamp,Record Type,Historic Glucose mmol/L,"
        + "Scan Glucose mmol/L,Non-numeric Rapid-Acting Insulin,Rapid-Acting Insulin (units),"
        + "Non-numeric Food,Carbohydrates (grams),Carbohydrates (servings),"
        + "Non-numeric Long-Acting Insulin,Long-Acting Insulin Value (units),Notes,"
        + "Strip Glucose mmol/L,Ketone mmol/L,Meal Insulin (units),Correction Insulin (units),"
        + "User Change Insulin (units)",
    "FreeStyle LibreLink,ABC,05-10-2026 07:00,0,6.1,,,,,,,,,,,,,,",
    "FreeStyle LibreLink,ABC,05-10-2026 07:31,1,,6.4,,,,,,,,,,,,,",
    "FreeStyle LibreLink,ABC,05-10-2026 07:32,4,,,,5,,,,,,,,,,,",
    "FreeStyle LibreLink,ABC,05-10-2026 07:33,5,,,,,,45,,,,,,,,,",
    "FreeStyle LibreLink,ABC,05-10-2026 07:45,0,LO,,,,,,,,,,,,,,",
    "FreeStyle LibreLink,ABC,05-10-2026 22:00,4,,,,,,,,,16,,,,,,",
].join("\n")

/** a Dexcom Clarity export (shortened) */
const clarity = [
    "Index,Timestamp (YYYY-MM-DDThh:mm:ss),Event Type,Event Subtype,Patient Info,"
        + "Device Info,Source Device ID,Glucose Value (mg/dL),Insulin Value (u),"
        + "Carb Value (grams),Duration (hh:mm:ss),Glucose Rate of Change (mg/dL/min),"
        + "Transmitter Time (Long Integer),Transmitter ID",
    "1,,FirstName,,A,,,,,,,,,",
    "2,,Device,,,G7,,,,,,,,",
    "3,2026-10-05T07:00:00,EGV,,,,iPhone,110,,,,,1000,X1",
    "4,2026-10-05T07:30:00,Insulin,Fast-Acting,,,iPhone,,5,,,,,",
    "5,2026-10-05T07:30:00,Carbs,,,,iPhone,,,45,,,,",
    "6,2026-10-05T17:00:00,Exercise,Heavy,,,iPhone,,,,00:45:00,,,",
    "7,2026-10-05T18:00:00,EGV,,,,iPhone,High,,,,,1000,X1",
    "8,2026-10-05T22:00:00,Insulin,Long-Acting,,,iPhone,,16,,,,,",
    "9,2026-10-05T22:05:00,Alert,High,,,iPhone,,,,,,,",
].join("\n")

describe("DeviceExports", () => {

    describe("#parseLibreViewTime", () => {
        it("should read UK dates day first", () => {
            expect(parseLibreViewTime("05-10-2026 07:30")).to.deep.equal(at(7, 30))
        })
        it("should read US dates with AM and PM month first", () => {
            expect(parseLibreViewTime("10-05-2026 07:30 PM")).to.deep.equal(at(19, 30))
            expect(parseLibreViewTime("10-05-2026 12:15 AM")).to.deep.equal(at(0, 15))
        })
        it("should reject dates that do not exist", () => {
            expect(parseLibreViewTime("31-02-2026 07:30")).to.be.undefined
        })
    })

    describe("#readPatientData", () => {
        it("should read a LibreView export", () => {
            const { events, source, notes } = readPatientData(libreView)
            expect(source).to.equal("LibreView export")
            expect(events).to.deep.equal([
                { time: at(7), type: "glucose", value: 6.1 },
                { time: at(7, 31), type: "glucose", value: 6.4 },
                { time: at(7, 32), type: "bolus", value: 5 },
                { time: at(7, 33), type: "carbs", value: 45 },
                { time: at(7, 45), type: "glucose", value: 2.2 },
                { time: at(22), type: "longacting", value: 16, insulin: "glargine" },
            ])
            expect(notes.join(" ")).to.contain("taken as glargine")
        })

        it("should read a Dexcom Clarity export in mg/dl", () => {
            const { events, source, notes } = readPatientData(clarity)
            expect(source).to.equal("Dexcom Clarity export")
            expect(events.map((e) => [e.type, Number(e.value.toFixed(1))])).to.deep.equal([
                ["glucose", 6.1],
                ["bolus", 5],
                ["carbs", 45],
                ["exercise", 70],
                ["glucose", 22.2],
                ["longacting", 16],
            ])
            expect(events[3].duration).to.equal(45)
            expect(notes.join(" ")).to.contain("1 other entries (such as alert) were not used")
        })

        it("should read Nightscout entries and treatments", () => {
            const json = JSON.stringify([
                { type: "sgv", sgv: 108, date: at(7).valueOf() },
                { eventType: "Meal Bolus", created_at: at(7, 30).toISOString(),
                    insulin: 5, carbs: 45 },
                { eventType: "Correction Bolus", created_at: at(12).toISOString(),
                    insulin: 2, carbs: null },
                { eventType: "Temp Basal", created_at: at(13).toISOString(), rate: 0.5 },
                { eventType: "Note", created_at: at(22).toISOString(), insulin: 16,
                    insulinInjections: '[{"insulin":"Tresiba","units":16}]' },
            ])
            const { events, source, notes } = readPatientData(json)
            expect(source).to.equal("Nightscout download")
            expect(events.map((e) => [e.type, Number(e.value.toFixed(1)), e.insulin]))
                .to.deep.equal([
                    ["glucose", 6, undefined],
                    ["bolus", 5, undefined],
                    ["carbs", 45, undefined],
                    ["bolus", 2, undefined],
                    ["longacting", 16, "degludec"],
                ])
            expect(notes.join(" ")).to.contain("1 pump basal changes were not used")
        })

        it("should read Nightscout treatments timed with timestamp or mills", () => {
            const { events } = readPatientData(JSON.stringify([
                { eventType: "Correction Bolus", timestamp: at(12).toISOString(), insulin: 2 },
                { eventType: "Carb Correction", mills: at(15).valueOf(), carbs: 15 },
            ]))
            expect(events).to.deep.equal([
                { time: at(12), type: "bolus", value: 2 },
                { time: at(15), type: "carbs", value: 15 },
            ])
        })

        it("should read SweetSpot CSV files as before", () => {
            const { events, source } = readPatientData(
                "time,type,value\n2026-10-05 08:00,bolus,4\n")
            expect(source).to.equal("SweetSpot CSV file")
            expect(events).to.deep.equal([{ time: at(8), type: "bolus", value: 4 }])
        })

        it("should say when an export has nothing to use", () => {
            expect(() => readPatientData(clarity.split("\n").slice(0, 3).join("\n")))
                .to.throw("No glucose readings, insulin or carbs found in this Dexcom Clarity export")
            expect(() => readPatientData("[1, 2]")).to.throw("not a Nightscout download")
        })
    })

    describe("sample files in examples/PatientData", () => {
        const sample = (name: string) => readPatientData(readFileSync(
            new URL("../../examples/PatientData/" + name, import.meta.url), "utf8"))
        const count = (events: { type: string }[], type: string) =>
            events.filter((e) => e.type === type).length

        for (const [name, source] of [
            ["SampleDayLibreView.csv", "LibreView export"],
            ["SampleDayDexcomClarity.csv", "Dexcom Clarity export"],
        ]) {
            it(`should read ${name}`, () => {
                const { events, source: found } = sample(name)
                expect(found).to.equal(source)
                expect(count(events, "glucose")).to.be.at.least(96)
                expect(count(events, "bolus")).to.equal(3)
                expect(count(events, "carbs")).to.equal(3)
                expect(count(events, "longacting")).to.equal(1)
            })
        }

        it("should read the Nightscout entries and treatments", () => {
            const entries = sample("SampleDayNightscout-entries.json")
            const treatments = sample("SampleDayNightscout-treatments.json")
            expect(count(entries.events, "glucose")).to.equal(96)
            expect(count(treatments.events, "bolus")).to.equal(3)
            expect(count(treatments.events, "carbs")).to.equal(3)
            expect(count(treatments.events, "exercise")).to.equal(1)
            expect(treatments.events.find((e) => e.type === "longacting"))
                .to.include({ value: 16, insulin: "glargine" })
        })
    })
})
